#!/usr/bin/env node
/**
 * Validate the fumadocs navigation files under docs/ and spec/ (AISDLC-854).
 *
 * Every page named in a meta.json must resolve to a sibling `<page>.md`,
 * a sub-directory, or (for `index`) an index.md / README.md. Separators
 * (`---Title---`) are allowed. `rfc-registry` is generated by the site build.
 * Entries may not escape the meta.json directory.
 *
 * Usage: node scripts/check-docs-nav.mjs
 */
import { existsSync, readFileSync, statSync } from 'node:fs';
import { join, dirname, resolve, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

export const NAV_FILES = [
  'docs/meta.json',
  'docs/getting-started/meta.json',
  'docs/concepts/meta.json',
  'docs/tutorials/meta.json',
  'docs/api-reference/meta.json',
  'docs/whitepapers/meta.json',
  'spec/meta.json',
];

const GENERATED = new Set(['docs/meta.json:rfc-registry']);

export function checkNav(root, files = NAV_FILES) {
  const errors = [];
  for (const rel of files) {
    const file = join(root, rel);
    if (!existsSync(file)) {
      errors.push(`${rel}: missing`);
      continue;
    }
    let meta;
    try {
      meta = JSON.parse(readFileSync(file, 'utf8'));
    } catch (e) {
      errors.push(`${rel}: invalid JSON (${e.message})`);
      continue;
    }
    if (typeof meta.title !== 'string' || !Array.isArray(meta.pages)) {
      errors.push(`${rel}: needs string "title" and array "pages"`);
      continue;
    }
    const dir = dirname(file);
    for (const page of meta.pages) {
      if (typeof page !== 'string') {
        errors.push(`${rel}: non-string page entry`);
        continue;
      }
      if (/^---.*---$/.test(page) || GENERATED.has(`${rel}:${page}`)) continue;
      const target = resolve(dir, page);
      const r = relative(root, target);
      if (r.startsWith('..') || !/^(docs|spec)(\/|$)/.test(r.split('\\').join('/'))) {
        errors.push(`${rel}: "${page}" points outside docs/ or spec/`);
        continue;
      }
      const ok =
        page === 'index'
          ? ['index.md', 'README.md'].some((n) => existsSync(join(dir, n)))
          : existsSync(`${target}.md`) || (existsSync(target) && statSync(target).isDirectory());
      if (!ok) errors.push(`${rel}: page "${page}" does not exist`);
    }
  }
  return errors;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
  const errors = checkNav(root);
  if (errors.length) {
    for (const e of errors) console.error(`check-docs-nav: ${e}`);
    process.exit(1);
  }
  console.log(`check-docs-nav: ${NAV_FILES.length} navigation files valid`);
}
